/// Looks up a place name (case-insensitive; tries the whole text, then each comma-separated
/// part, then the first words — "Bengaluru Central" → Bengaluru).
pub fn lookup(name: &str) -> Option<(f32, f32)> {
    let n = name.trim().to_lowercase();
    let find = |s: &str| PLACES.iter().find(|p| p.0 == s).map(|p| (p.1, p.2));
    if let Some(p) = find(&n) {
        return Some(p);
    }
    for part in n.split(',') {
        if let Some(p) = find(part.trim()) {
            return Some(p);
        }
    }
    let words: Vec<&str> = n.split_whitespace().collect();
    for k in (1..words.len()).rev() {
        if let Some(p) = find(&words.get(..k).unwrap_or(&[]).join(" ")) {
            return Some(p);
        }
    }
    None
}
